//! generated by claude, needs rewrite sometime

use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode};

use runtime_run_flags::RuntimeFlags;
use tracing::{error, info};

/// generated examples go here, relative to the workspace root. the folder is gitignored
const EXAMPLES_DIR: &str = "tests/examples/source_to_tbpk/generated";
/// packs from `--auto` go in a folder per example under here, so they don't overwrite each other
const PACKS_DIR: &str = "out/tbpk_generator";

const KIB: u64 = 1024;
const MIB: u64 = 1024 * KIB;

/// files per pack folder, so no single folder gets huge
const FILES_PER_GROUP: usize = 20;

/// default `--min` and `--max` for `--type random`
const DEFAULT_RANDOM_MIN: u64 = 1;
const DEFAULT_RANDOM_MAX: u64 = MIB;

/// the size classes, in bytes, inclusive. large starts above the 256 KiB large file threshold
const XSMALL: (u64, u64) = (1, 64);
const SMALL: (u64, u64) = (65, 4 * KIB);
const LARGE: (u64, u64) = (256 * KIB + 1, 4 * MIB);
const XLARGE: (u64, u64) = (8 * MIB, 16 * MIB);

/// how random the file bytes are, which decides how well they compress
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Entropy {
    /// long runs of a few byte values
    Low,
    /// a small set of random words repeated in random order, with some noise
    Med,
    /// every byte random
    High,
}

impl Entropy {
    fn parse(name: &str) -> Result<Self, String> {
        match name {
            "low" => Ok(Entropy::Low),
            "med" => Ok(Entropy::Med),
            "high" => Ok(Entropy::High),
            other => Err(format!("--entropy is `{other}`, expected low, med or high")),
        }
    }
}

/// byte values low entropy runs are made of
const LOW_BYTES: [u8; 4] = [0x00, 0x20, 0x41, 0xff];
/// how many words med entropy files are built from
const MED_WORDS: usize = 256;

#[derive(Clone, Copy, Debug)]
enum Kind {
    XSmall,
    Small,
    Large,
    XLarge,
    /// small and large files
    Mix,
    /// files from every size class
    XMix,
    Random {
        min: u64,
        max: u64,
    },
}

impl Kind {
    fn parse(name: &str, min: Option<u64>, max: Option<u64>) -> Result<Self, String> {
        let kind = match name {
            "xsmall" => Kind::XSmall,
            "small" => Kind::Small,
            "large" => Kind::Large,
            "xlarge" => Kind::XLarge,
            "mix" => Kind::Mix,
            "xmix" => Kind::XMix,
            "random" => {
                let min = min.unwrap_or(DEFAULT_RANDOM_MIN);
                let max = max.unwrap_or(DEFAULT_RANDOM_MAX);
                if min > max {
                    return Err(format!("--min {min} is bigger than --max {max}"));
                }
                return Ok(Kind::Random { min, max });
            }
            other => {
                return Err(format!(
                    "--type is `{other}`, expected small, large, xsmall, xlarge, mix, xmix or random"
                ));
            }
        };
        if min.is_some() || max.is_some() {
            return Err("--min and --max only work with --type random".into());
        }
        Ok(kind)
    }

    fn name(&self) -> &'static str {
        match self {
            Kind::XSmall => "xsmall",
            Kind::Small => "small",
            Kind::Large => "large",
            Kind::XLarge => "xlarge",
            Kind::Mix => "mix",
            Kind::XMix => "xmix",
            Kind::Random { .. } => "random",
        }
    }

    /// files per side when `--count` isn't given
    fn default_count(&self) -> usize {
        match self {
            Kind::XSmall => 500,
            Kind::Small => 250,
            Kind::Large | Kind::XLarge => 25,
            Kind::Mix | Kind::XMix => 100,
            Kind::Random { .. } => 50,
        }
    }

    /// picks a file size from two random numbers
    fn size(&self, pick: u64, roll: u64) -> u64 {
        let (min, max) = match *self {
            Kind::XSmall => XSMALL,
            Kind::Small => SMALL,
            Kind::Large => LARGE,
            Kind::XLarge => XLARGE,
            Kind::Mix => [SMALL, LARGE][(pick % 2) as usize],
            Kind::XMix => [XSMALL, SMALL, LARGE, XLARGE][(pick % 4) as usize],
            Kind::Random { min, max } => (min, max),
        };
        // the range can only be all of u64 for random, and then any roll fits
        match (max - min).checked_add(1) {
            Some(span) => min + roll % span,
            None => roll,
        }
    }
}

/// one example folder. the name only depends on the settings, so the same settings always
/// map to the same folder, and the file contents are seeded from the name and path
struct Example {
    kind: Kind,
    /// files on each side, shared files count for both sides
    count: usize,
    entropy: Entropy,
}

impl Example {
    /// high entropy has no suffix, it was the only kind before `--entropy` existed
    fn name(&self) -> String {
        match self.entropy {
            Entropy::Low => format!("{}_low", self.seed()),
            Entropy::Med => format!("{}_med", self.seed()),
            Entropy::High => self.seed(),
        }
    }

    /// the name without the entropy, so the file sizes match across entropies
    fn seed(&self) -> String {
        match self.kind {
            Kind::Random { min, max } => format!("random_{}_{min}_{max}", self.count),
            kind => format!("{}_{}", kind.name(), self.count),
        }
    }

    /// (table, folder, files). about half the files are shared, the rest are split per side
    fn sections(&self) -> [(&'static str, &'static str, usize); 3] {
        let shared = self.count.div_ceil(2);
        let side = self.count - shared;
        [
            ("assets", "shared", shared),
            ("client.assets", "client", side),
            ("server.assets", "server", side),
        ]
    }
}

/// read from the run flags:
/// `--type <small|large|xsmall|xlarge|mix|xmix|random>` which example to make, without it
/// every preset is made
/// `--count <n>` files per side, defaults per type
/// `--min <bytes>` `--max <bytes>` file size range for `--type random`, defaults to 1 B - 1 MiB
/// `--entropy <low|med|high>` how random the file bytes are, defaults to high
/// `--auto` run `cargo pkgen` on the example afterwards
struct Args {
    examples: Vec<Example>,
    auto: bool,
}

impl Args {
    fn from_flags(flags: &RuntimeFlags) -> Result<Self, String> {
        let flags = flags.get_flags();
        for flag in flags.keys() {
            if !["--type", "--count", "--min", "--max", "--entropy", "--auto"]
                .contains(&flag.as_str())
            {
                return Err(format!("unknown flag {flag}"));
            }
        }

        let value = |flag: &str| -> Result<Option<&String>, String> {
            match flags.get(flag) {
                None => Ok(None),
                Some(values) => match values.as_slice() {
                    [value] => Ok(Some(value)),
                    _ => Err(format!("{flag} takes exactly one value")),
                },
            }
        };
        let number = |flag: &str| -> Result<Option<u64>, String> {
            value(flag)?
                .map(|v| {
                    v.parse::<u64>()
                        .map_err(|_| format!("{flag} is `{v}`, expected a whole number"))
                })
                .transpose()
        };

        let auto = match flags.get("--auto") {
            None => false,
            Some(values) if values.is_empty() => true,
            Some(_) => return Err("--auto doesn't take a value".into()),
        };
        let count = number("--count")?
            .map(|count| {
                usize::try_from(count)
                    .ok()
                    .filter(|&count| count > 0)
                    .ok_or_else(|| format!("--count is {count}, expected at least 1"))
            })
            .transpose()?;
        let min = number("--min")?;
        let max = number("--max")?;
        let entropy = value("--entropy")?.map_or(Ok(Entropy::High), |e| Entropy::parse(e))?;

        let Some(kind) = value("--type")? else {
            if count.is_some() || min.is_some() || max.is_some() {
                return Err("--count, --min and --max need a --type".into());
            }
            return Ok(Self {
                examples: presets(entropy),
                auto,
            });
        };

        let kind = Kind::parse(kind, min, max)?;
        Ok(Self {
            examples: vec![Example {
                kind,
                count: count.unwrap_or(kind.default_count()),
                entropy,
            }],
            auto,
        })
    }
}

/// what runs without `--type`, one of each type at its default count
fn presets(entropy: Entropy) -> Vec<Example> {
    [
        Kind::XSmall,
        Kind::Small,
        Kind::Large,
        Kind::XLarge,
        Kind::Mix,
        Kind::XMix,
        Kind::Random {
            min: DEFAULT_RANDOM_MIN,
            max: DEFAULT_RANDOM_MAX,
        },
    ]
    .into_iter()
    .map(|kind| Example {
        kind,
        count: kind.default_count(),
        entropy,
    })
    .collect()
}

fn main() -> ExitCode {
    // returning ExitCode (instead of process::exit) lets the guard drop and flush logs
    let _guard = runtime_logging::init_logging("Tbpk", "Regen");

    let args = match Args::from_flags(&RuntimeFlags::read()) {
        Ok(args) => args,
        Err(msg) => {
            error!("{msg}");
            return ExitCode::FAILURE;
        }
    };

    // the workspace root, so this works no matter where cargo is run from
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");

    let mut failed = false;
    for example in &args.examples {
        let name = example.name();
        let dir = Path::new(EXAMPLES_DIR).join(&name);

        if root.join(&dir).join("manifest.toml").exists() {
            info!("{name} already exists at {}, not generating", dir.display());
        } else {
            let start = std::time::Instant::now();
            info!("Generating {name} at {}", dir.display());
            if let Err(msg) = generate(example, &root.join(&dir)) {
                error!("error on generate {name}: {msg}");
                failed = true;
                continue;
            }
            info!("Generated {name} in {:?}", start.elapsed());
        }

        if args.auto && !pkgen(&root, &name, &dir) {
            failed = true;
        }
    }

    if failed {
        ExitCode::FAILURE
    } else {
        ExitCode::SUCCESS
    }
}

/// writes into a temp folder and renames it at the end, so a half written example is
/// never mistaken for a finished one
fn generate(example: &Example, dir: &Path) -> Result<(), String> {
    let tmp = dir.with_extension("tmp");
    if tmp.exists() {
        fs::remove_dir_all(&tmp).map_err(|e| format!("`{}`: {e}", tmp.display()))?;
    }

    let name = example.name();
    let seed = example.seed();
    let mut manifest =
        String::from("realm_id = 1\nowner_id = 1\npack_version = 1\naccess = \"free\"\n");
    let mut total = 0;

    for (table, side, files) in example.sections() {
        manifest.push_str(&format!("\n[{table}]\n"));
        for i in 0..files {
            let group = format!("group{:02}", i / FILES_PER_GROUP);
            let item = format!("item{i:04}");
            let path = format!("{side}/{group}/{item}.bin");

            let folder = tmp.join(side).join(&group);
            fs::create_dir_all(&folder).map_err(|e| format!("`{}`: {e}", folder.display()))?;
            total += write_file(example, &seed, &path, &tmp.join(&path))
                .map_err(|e| format!("`{path}`: {e}"))?;

            manifest.push_str(&format!("\"self:{side}/{group}/{item}\" = \"{path}\"\n"));
        }
    }

    fs::write(tmp.join("manifest.toml"), manifest).map_err(|e| e.to_string())?;
    fs::rename(&tmp, dir).map_err(|e| format!("`{}`: {e}", dir.display()))?;
    info!("{name} has {} bytes of files", total);
    Ok(())
}

/// everything comes from a blake3 stream keyed by the seed and file path, so it's the
/// same every run. returns the file size
fn write_file(example: &Example, seed: &str, path: &str, out: &Path) -> std::io::Result<u64> {
    let mut stream = blake3::Hasher::new_derive_key("terobit example_generator")
        .update(seed.as_bytes())
        .update(&[0])
        .update(path.as_bytes())
        .finalize_xof();

    let mut header = [0; 16];
    stream.fill(&mut header);
    let [pick, roll] = [&header[..8], &header[8..]]
        .map(|bytes| u64::from_le_bytes(bytes.try_into().unwrap_or_default()));
    let size = example.kind.size(pick, roll);
    let mut content = Content::new(example.entropy, stream);

    let mut file = fs::File::create(out)?;
    let mut buf = vec![0; MIB as usize];
    let mut left = size;
    while left > 0 {
        let n = left.min(buf.len() as u64) as usize;
        content.fill(&mut buf[..n]);
        file.write_all(&buf[..n])?;
        left -= n as u64;
    }
    Ok(size)
}

/// makes a file's bytes at some entropy, carrying patterns across `fill` calls
struct Content {
    entropy: Entropy,
    stream: blake3::OutputReader,
    /// random bytes read ahead, small reads straight from the stream are slow
    rolls: [u8; 4096],
    roll_at: usize,
    /// med: the words the file is built from
    words: Vec<Vec<u8>>,
    /// made but not written yet
    piece: Vec<u8>,
    piece_at: usize,
}

impl Content {
    fn new(entropy: Entropy, stream: blake3::OutputReader) -> Self {
        let mut content = Self {
            entropy,
            stream,
            rolls: [0; 4096],
            roll_at: 4096,
            words: Vec::new(),
            piece: Vec::new(),
            piece_at: 0,
        };
        if entropy == Entropy::Med {
            content.words = (0..MED_WORDS)
                .map(|_| {
                    let len = 4 + content.roll() as usize % 29;
                    (0..len).map(|_| content.roll()).collect()
                })
                .collect();
        }
        content
    }

    fn roll(&mut self) -> u8 {
        if self.roll_at == self.rolls.len() {
            self.stream.fill(&mut self.rolls);
            self.roll_at = 0;
        }
        self.roll_at += 1;
        self.rolls[self.roll_at - 1]
    }

    fn fill(&mut self, buf: &mut [u8]) {
        if self.entropy == Entropy::High {
            self.stream.fill(buf);
            return;
        }

        let mut done = 0;
        while done < buf.len() {
            if self.piece_at == self.piece.len() {
                self.next_piece();
            }
            let n = (buf.len() - done).min(self.piece.len() - self.piece_at);
            buf[done..done + n].copy_from_slice(&self.piece[self.piece_at..self.piece_at + n]);
            done += n;
            self.piece_at += n;
        }
    }

    fn next_piece(&mut self) {
        self.piece.clear();
        self.piece_at = 0;
        match self.entropy {
            Entropy::Low => {
                let byte = LOW_BYTES[self.roll() as usize % LOW_BYTES.len()];
                let len = 16 + self.roll() as usize;
                self.piece.resize(len, byte);
            }
            Entropy::Med => {
                // one in eight pieces is a few bytes of noise, the rest are words
                if self.roll().is_multiple_of(8) {
                    let len = 1 + self.roll() as usize % 8;
                    for _ in 0..len {
                        let byte = self.roll();
                        self.piece.push(byte);
                    }
                } else {
                    let word = self.roll() as usize % MED_WORDS;
                    self.piece.extend_from_slice(&self.words[word]);
                }
            }
            Entropy::High => unreachable!("high entropy fills straight from the stream"),
        }
    }
}

/// `cargo pkgen` with the example's manifest. later flags win, so these replace the alias's
fn pkgen(root: &Path, name: &str, dir: &Path) -> bool {
    let manifest = dir.join("manifest.toml");
    let out: PathBuf = Path::new(PACKS_DIR).join(name);
    info!(
        "Running cargo pkgen on {name}, packs go to {}",
        out.display()
    );

    let cargo = std::env::var("CARGO").unwrap_or_else(|_| "cargo".into());
    match Command::new(cargo)
        .current_dir(root)
        .arg("pkgen")
        .arg("--manifest")
        .arg(&manifest)
        .arg("--out")
        .arg(&out)
        .status()
    {
        Ok(status) if status.success() => true,
        Ok(status) => {
            error!("cargo pkgen on {name} failed with {status}");
            false
        }
        Err(e) => {
            error!("Failed to start cargo: {e}");
            false
        }
    }
}

#[cfg(test)]
mod fn_tests {
    use super::*;

    fn args(args: &[&str]) -> Result<Args, String> {
        Args::from_flags(&RuntimeFlags::from_args(args.iter().map(|a| a.to_string())))
    }

    #[test]
    fn no_flags_is_every_preset() {
        let args = args(&[]).unwrap();
        assert_eq!(args.examples.len(), 7);
        assert!(!args.auto);
    }

    #[test]
    fn names_are_deterministic() {
        let args = args(&[
            "--type", "random", "--count", "3", "--min", "5", "--max", "9",
        ])
        .unwrap();
        assert_eq!(args.examples[0].name(), "random_3_5_9");
        let args = self::args(&["--type", "xlarge", "--auto"]).unwrap();
        assert_eq!(args.examples[0].name(), "xlarge_25");
        assert!(args.auto);
        let args = self::args(&["--type", "small", "--entropy", "med"]).unwrap();
        assert_eq!(args.examples[0].name(), "small_250_med");
        assert_eq!(args.examples[0].seed(), "small_250");
    }

    #[test]
    fn entropy_applies_to_presets() {
        let args = args(&["--entropy", "low"]).unwrap();
        assert!(args.examples.iter().all(|e| e.entropy == Entropy::Low));
    }

    #[test]
    fn content_is_deterministic_across_fills() {
        for entropy in [Entropy::Low, Entropy::Med, Entropy::High] {
            let stream = || blake3::Hasher::new().update(b"seed").finalize_xof();
            let mut whole = vec![0; 10_000];
            Content::new(entropy, stream()).fill(&mut whole);

            let mut split = vec![0; 10_000];
            let mut content = Content::new(entropy, stream());
            for chunk in split.chunks_mut(333) {
                content.fill(chunk);
            }
            assert_eq!(whole, split, "{entropy:?}");
        }
    }

    #[test]
    fn rejects_bad_flags() {
        assert!(args(&["--type", "huge"]).is_err());
        assert!(args(&["--type", "small", "--min", "1"]).is_err());
        assert!(args(&["--type", "random", "--min", "9", "--max", "5"]).is_err());
        assert!(args(&["--type", "small", "--count", "0"]).is_err());
        assert!(args(&["--count", "5"]).is_err());
        assert!(args(&["--auto", "yes"]).is_err());
        assert!(args(&["--size", "5"]).is_err());
        assert!(args(&["--entropy", "max"]).is_err());
    }

    #[test]
    fn sides_get_count_files() {
        for count in [1, 2, 25] {
            let [shared, client, server] = Example {
                kind: Kind::Small,
                count,
                entropy: Entropy::High,
            }
            .sections();
            assert_eq!(shared.2 + client.2, count);
            assert_eq!(shared.2 + server.2, count);
        }
    }

    #[test]
    fn sizes_stay_in_range() {
        let kind = Kind::Random { min: 10, max: 12 };
        for roll in 0..100 {
            assert!((10..=12).contains(&kind.size(roll, roll)));
        }
        assert_eq!(
            Kind::Random {
                min: 0,
                max: u64::MAX
            }
            .size(0, 7),
            7
        );
    }
}
